window.addEventListener('pagehide', () => { restoreWorld = null; interaction.dispose(); navigation.dispose(); void session.stop(); bench?.dispose(); });
window.render_game_to_text = () => JSON.stringify({ mode: benchMode ? 'robot workbench' : preview ? 'controls preview' : live ? 'live world' : connecting ? 'connecting' : 'start', frameMode: benchMode ? 'local 3D workbench' : frameMode, world, keys: [...keys], inputs: sentMotion, interaction: interaction.getState(), navigation: navigation.getState(), model: { running: lastModelState.running || false, paused: lastModelState.paused || false, action: lastModelState.current_action, chunk, frames, activePrompt }, computer: { note: $('notes').value, training }, bench: bench?.getState() || null, dialog: document.querySelector('dialog[open]')?.id || null, journey: journey.slice(-4), coordinates: 'Model-generated video has no verified 3D position. Selection coordinates run 0–1 from top-left of the held video frame. Masks come from local image segmentation. Workbench uses exact local 3D geometry.' });
window.advanceTime = async ms => { await new Promise(resolve => setTimeout(resolve, Math.min(ms, 500))); };
fetch('/api/status').then(response => response.json()).then(data => { if (!data.hasKey) notice('Live worlds need the shared Reactor API key.', true, true); else log('Reactor key available.'); }).catch(() => notice('Local server is not responding.', true));
refreshWorld(); renderJournal();
void locationsReady.then(() => {
  showPlay();
  if (new URLSearchParams(location.search).has('preview')) $('preview').click();
  else void start();
});
